CREATE TABLE knowledge_meta(run_id TEXT PRIMARY KEY REFERENCES runs(run_id), revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0), cursor INTEGER NOT NULL DEFAULT 0 CHECK(cursor>=0), llm_limit INTEGER CHECK(llm_limit IS NULL OR llm_limit>=0));
CREATE TABLE knowledge_records(run_id TEXT NOT NULL REFERENCES runs(run_id), compartment TEXT NOT NULL CHECK(compartment IN ('history','preferences','calibration','lessons')), scope TEXT NOT NULL, record_key TEXT NOT NULL, schema_version TEXT NOT NULL DEFAULT 'self-improve.v1' CHECK(schema_version='self-improve.v1'), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), PRIMARY KEY(run_id,compartment,scope,record_key));
CREATE TABLE knowledge_receipts(run_id TEXT NOT NULL REFERENCES runs(run_id), receipt_key TEXT NOT NULL, payload_hash TEXT NOT NULL, schema_version TEXT NOT NULL DEFAULT 'self-improve.v1' CHECK(schema_version='self-improve.v1'), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), PRIMARY KEY(run_id,receipt_key));
CREATE TABLE skill_versions(run_id TEXT NOT NULL, shop_id TEXT NOT NULL, skill_id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), created_day INTEGER NOT NULL, effective_from_day INTEGER NOT NULL CHECK(effective_from_day=created_day+1), schema_version TEXT NOT NULL DEFAULT 'self-improve.v1' CHECK(schema_version='self-improve.v1'), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), PRIMARY KEY(run_id,shop_id,skill_id,version), UNIQUE(run_id,shop_id,skill_id,created_day), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
CREATE TABLE night_snapshots(run_id TEXT NOT NULL, day INTEGER NOT NULL CHECK(day BETWEEN 1 AND 7), shop_id TEXT NOT NULL, snapshot_hash TEXT NOT NULL, schema_version TEXT NOT NULL DEFAULT 'self-improve.v1' CHECK(schema_version='self-improve.v1'), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), PRIMARY KEY(run_id,day), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
CREATE TABLE reflection_receipts(run_id TEXT NOT NULL, day INTEGER NOT NULL, snapshot_hash TEXT NOT NULL, owner_token TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('reserved','completed','failed','unknown')), schema_version TEXT NOT NULL DEFAULT 'self-improve.v1' CHECK(schema_version='self-improve.v1'), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), PRIMARY KEY(run_id,day), FOREIGN KEY(run_id,day) REFERENCES night_snapshots(run_id,day));
CREATE TABLE night_commits(run_id TEXT NOT NULL, day INTEGER NOT NULL, shop_id TEXT NOT NULL, snapshot_hash TEXT NOT NULL, publication_hash TEXT NOT NULL, schema_version TEXT NOT NULL DEFAULT 'self-improve.v1' CHECK(schema_version='self-improve.v1'), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), PRIMARY KEY(run_id,day), FOREIGN KEY(run_id,day) REFERENCES night_snapshots(run_id,day), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
CREATE TABLE llm_call_reservations(run_id TEXT NOT NULL REFERENCES runs(run_id), call_id TEXT NOT NULL, reserved_at TEXT NOT NULL, PRIMARY KEY(run_id,call_id));
